func TestProposeSkillConventionsCacheInvalidatesOnContentChange(t *testing.T) {
	now := time.Now()
	brainDir := t.TempDir()
	newCorpusAtDir(t, brainDir)
	facts := []factRecord{
		{ID: "fact:pinned", Kind: "convention", Branch: "main", Status: "active",
